"""10 kb KR-balanced contact map at the Rao et al. Figure 6B locus.

The source is the combined GM12878 primary + replicate Hi-C map from GSE63525, hg19 chr4:
20,550,000-22,550,000. The 200-bin region was extracted with indexed .hic byte-range queries;
only this region's KR vector and sparse raw upper-triangle counts are inlined below. The source
file is 54.7 GB, but the chart example is standalone and reads no local files or network.

KR-balanced intensity is raw_count / (KR_i * KR_j), verified against the source's KR matrix.
The color scale is logarithmic from positive observed values through the 99.5th percentile;
values above that cap saturate. Gray cells are recorded as zero contacts. All 200 bins have valid
KR normalization values, so no cell is masked or unmeasured. The sparse .hic matrix omits zeros.

Source: UCSC hg19 mirror of GSE63525_GM12878_insitu_primary+replicate_combined.hic, ETag
cbefd3966-594578385481d, Last-Modified 2019-10-07, 54,743,873,894 bytes. The bounded regional
JSON has SHA-256 6224f2008fece6f750270a6c7311c2549c1af0fa734892e174047d1bd8356c8a. Rebuild it
with ``uv run --with hic-straw==1.3.1 python website/scripts/extract_landmark_data.py
--fetch-rao /tmp/rao-region.json``; the extractor verifies the local JSON offline.
"""

import altair as alt
import numpy as np
import polars as pl

import dysonsphere as ds

SOURCE_URL = "https://hgdownload.soe.ucsc.edu/gbdb/hg19/bbi/hic/GSE63525_GM12878_insitu_primary+replicate_combined.hic"
PAPER_DOI = "10.1016/j.cell.2014.11.021"
SOURCE_SHA256 = "6224f2008fece6f750270a6c7311c2549c1af0fa734892e174047d1bd8356c8a"
ZERO_COLOR = ds.palettes.accents["grey"]

# Call once; the viridis heatmap ramp is continuous and shared across light/dark exports.
ds.theme(
    width=300,
    height=300,
    closed=True,
    viewPadding=False,
    rectPadding=0,
    outerPadding=0,
    heatmapPalette="viridis",
    heatmapPaletteDarkmode="viridis",
)

