n_bins = len(KR_VECTOR)
if n_bins != (REGION_END_BP - REGION_START_BP) // BIN_SIZE_BP:
    raise ValueError("The inline KR vector and region dimensions do not match")
contact_counts = np.zeros((n_bins, n_bins), dtype=np.int64)
for i, j, count in RAW_UPPER_RECORDS:
    contact_counts[i, j] = count
    if i != j:
        contact_counts[j, i] = count
kr_vector = np.asarray(KR_VECTOR, dtype=float)
balanced = contact_counts / (kr_vector[:, None] * kr_vector[None, :])
positive_values = balanced[contact_counts > 0]
color_max = float(np.quantile(positive_values, 0.995))
minimum_positive = float(positive_values.min())

