for i in range(n_bins):
    for j in range(i, n_bins):
        count = int(contact_counts[i, j])
        upper_rows.append({"i": i, "j": j, "raw_count": count, "kr_balanced": float(balanced[i, j])})

position_ticks_mb = [20.6, 21.0, 21.4, 21.8, 22.2, 22.5]
tick_bins = [round((value - REGION_START_BP / 1_000_000) / (BIN_SIZE_BP / 1_000_000)) for value in position_ticks_mb]
tick_labels = {index: [f"{value:.1f}"] for index, value in zip(tick_bins, position_ticks_mb)}
plot_x = alt.X(
    "x_index:Q",
    title="Position (Mb, hg19)",
    bin=alt.Bin(step=1, extent=[0, n_bins]),
    scale=alt.Scale(domain=[0, n_bins], nice=False),
    axis=alt.Axis(values=tick_bins, labelExpr=ds.label_expr(tick_labels), grid=False),
)
plot_y = alt.Y(
    "y_index:Q",
    title="Position (Mb, hg19)",
    bin=alt.Bin(step=1, extent=[0, n_bins]),
    scale=alt.Scale(domain=[0, n_bins], reverse=True, nice=False),
    axis=alt.Axis(values=tick_bins, labelExpr=ds.label_expr(tick_labels), grid=False),
)
contact_color = alt.condition(
    alt.datum.raw_count == 0,
    alt.value(ZERO_COLOR),
    alt.Color(
        "kr_balanced:Q",
        scale=alt.Scale(type="log", domain=[minimum_positive, color_max], nice=False),
        legend=alt.Legend(
            title=["KR-balanced contacts (log scale)", "gray = zero"],
            values=[1, 10, 100, 1000],
            format="~s",
        ),
    ),
)
chart = (
    alt.Chart(alt.Data(values=pl.DataFrame(upper_rows).to_dicts()))
    .transform_fold(["i", "j"], as_=["dimension", "index"])
    .transform_filter("datum.dimension === 'j' || datum.i !== datum.j")
    .transform_calculate(
        x_index="datum.dimension === 'j' ? datum.i : datum.j",
        y_index="datum.dimension === 'j' ? datum.j : datum.i",
    )
    .transform_calculate(
        x_center_mb=f"{REGION_START_BP / 1_000_000} + (datum.x_index + 0.5) * {BIN_SIZE_BP / 1_000_000}",
        y_center_mb=f"{REGION_START_BP / 1_000_000} + (datum.y_index + 0.5) * {BIN_SIZE_BP / 1_000_000}",
    )
    .mark_rect(stroke=None, clip=True)
    .encode(
        x=plot_x,
        y=plot_y,
        color=contact_color,
        tooltip=[
            alt.Tooltip("x_center_mb:Q", title="x center (Mb)", format=".3f"),
            alt.Tooltip("y_center_mb:Q", title="y center (Mb)", format=".3f"),
            alt.Tooltip("raw_count:Q", title="Raw contacts", format=","),
            alt.Tooltip("kr_balanced:Q", title="KR-balanced contacts", format=".3g"),
        ],
    )
)
